values
('bmlt-healthpolicy1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which is a key function of a health system?","translation":"","options":["Providing equitable health services","Maximizing hospital profit","Restricting primary care","Replacing prevention with treatment"],"correctIndex":0,"explanation":"A health system delivers promotive, preventive, curative, rehabilitative and palliative services.","explanationNe":"स्वास्थ्य प्रणालीले स्वास्थ्य प्रवर्द्धनदेखि उपचार, पुनर्स्थापना र पल्लिएटिभ सेवा प्रदान गर्छ।","topic":"Health system"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Primary health care is best described as:","translation":"","options":["First-contact, accessible essential care","Only specialist hospital care","Emergency surgery only","Private insurance administration"],"correctIndex":0,"explanation":"Primary health care is the accessible, community-oriented foundation of the health system.","explanationNe":"प्राथमिक स्वास्थ्य सेवा समुदायमै सहज रूपमा उपलब्ध हुने आधारभूत सेवा हो।","topic":"Primary health care"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Universal Health Coverage means people can obtain needed services:","translation":"","options":["Without financial hardship","Only after private insurance","Only in tertiary hospitals","Only during outbreaks"],"correctIndex":0,"explanation":"UHC combines access to needed quality services with protection from financial hardship.","explanationNe":"UHC ले आवश्यक गुणस्तरीय सेवा आर्थिक कठिनाइबिना पाउने सुनिश्चित गर्छ।","topic":"UHC"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which is an example of secondary-level health care?","translation":"","options":["District or general hospital specialist outpatient service","Home-based health awareness only","National policy formulation","International research agency"],"correctIndex":0,"explanation":"Secondary care commonly provides specialist services and referral-level hospital care.","explanationNe":"दोस्रो तहमा विशेषज्ञ सेवा र रेफरल अस्पतालको सेवा पर्छ।","topic":"Levels of care"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"The main purpose of a referral system is to:","translation":"","options":["Ensure patients reach an appropriate level of care","Prevent patients from accessing hospitals","Increase unnecessary investigations","Replace clinical documentation"],"correctIndex":0,"explanation":"Referral links levels of care and supports continuity and appropriate use of resources.","explanationNe":"रेफरल प्रणालीले बिरामीलाई आवश्यकताअनुसार उपयुक्त तहमा पुर्‍याउँछ।","topic":"Referral system"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Which is a health promotion activity?","translation":"","options":["Community education on healthy diet and activity","Only prescribing antibiotics","Surgical removal of a tumour","Reporting laboratory results"],"correctIndex":0,"explanation":"Health promotion enables people to improve control over their health.","explanationNe":"स्वास्थ्य प्रवर्द्धनले मानिसलाई आफ्नो स्वास्थ्य सुधार गर्न सक्षम बनाउँछ।","topic":"Health promotion"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Immunization is primarily classified as which level of prevention?","translation":"","options":["Primary","Secondary","Tertiary","Quaternary"],"correctIndex":0,"explanation":"Vaccination prevents disease before it occurs, so it is primary prevention.","explanationNe":"खोपले रोग हुनुअघि रोक्ने भएकाले प्राथमिक रोकथाम हो।","topic":"Levels of prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Screening for cervical cancer in an eligible population is an example of:","translation":"","options":["Secondary prevention","Primary prevention","Tertiary prevention","Palliative care"],"correctIndex":0,"explanation":"Screening aims to detect disease early, which is secondary prevention.","explanationNe":"स्क्रिनिङले रोग छिटो पत्ता लगाउँछ, त्यसैले यो द्वितीयक रोकथाम हो।","topic":"Levels of prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Rehabilitation after a stroke is mainly:","translation":"","options":["Tertiary prevention","Primary prevention","Primordial prevention","Health surveillance"],"correctIndex":0,"explanation":"Rehabilitation reduces disability and improves function after disease or injury.","explanationNe":"रोग वा चोटपछि अपाङ्गता घटाई कार्यक्षमता सुधार्नु तृतीयक रोकथाम हो।","topic":"Levels of prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Incidence measures:","translation":"","options":["New cases occurring in a population over a period","All existing cases at one point","Deaths only","Hospital beds per 1,000 people"],"correctIndex":0,"explanation":"Incidence counts new cases in a defined population during a specified period.","explanationNe":"Incidence ले निश्चित अवधिमा देखिएका नयाँ केस मापन गर्छ।","topic":"Health indicators"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Prevalence refers to:","translation":"","options":["All existing cases in a population at a specified time or period","Only newly diagnosed cases","Only deaths from a disease","Number of health workers"],"correctIndex":0,"explanation":"Prevalence includes existing cases, both old and new, at a defined time or period.","explanationNe":"Prevalence ले निश्चित समयमा रहेका पुराना र नयाँ सबै केस समेट्छ।","topic":"Health indicators"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"A disease surveillance system is used to:","translation":"","options":["Collect, analyse and interpret health data for action","Store data without review","Replace diagnosis","Provide treatment without assessment"],"correctIndex":0,"explanation":"Surveillance supports timely public health action through ongoing data collection and analysis.","explanationNe":"निरन्तर तथ्याङ्क संकलन र विश्लेषण गरी जनस्वास्थ्य कार्य गर्न surveillance उपयोगी हुन्छ।","topic":"Surveillance"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"When an outbreak is suspected, an early essential step is to:","translation":"","options":["Verify the diagnosis and confirm that an outbreak exists","Immediately close every health facility","Stop collecting specimens","Publish unverified names"],"correctIndex":0,"explanation":"Verification prevents misclassification and guides an appropriate investigation.","explanationNe":"रोग र प्रकोप पुष्टि गर्दा गलत निष्कर्षबाट बचेर उचित अनुसन्धान गर्न सकिन्छ।","topic":"Outbreak investigation"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"The first link in the chain of infection is commonly described as the:","translation":"","options":["Infectious agent","Portal of exit","Mode of transmission","Susceptible host"],"correctIndex":0,"explanation":"The infectious agent is the microorganism or other cause responsible for infection.","explanationNe":"संक्रमण गराउने सूक्ष्मजीव वा कारणलाई infectious agent भनिन्छ।","topic":"Infection prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Safe drinking water and proper sanitation mainly help prevent:","translation":"","options":["Water- and sanitation-related diseases","Genetic disorders","All congenital anomalies","All cancers"],"correctIndex":0,"explanation":"Safe water and sanitation reduce faecal-oral transmission and related infections.","explanationNe":"सुरक्षित पानी र सरसफाइले दिसा–मुख मार्गबाट सर्ने रोग घटाउँछ।","topic":"Environmental health"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"The cold chain is maintained to:","translation":"","options":["Keep vaccines within recommended temperature ranges","Freeze every vaccine","Store vaccines with food","Avoid recording vaccine stock"],"correctIndex":0,"explanation":"Cold-chain management preserves vaccine potency during storage and transport.","explanationNe":"खोपको प्रभावकारिता कायम राख्न भण्डारण र ढुवानीमा उपयुक्त तापक्रम राखिन्छ।","topic":"Immunization"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"A health indicator is useful because it:","translation":"","options":["Summarizes a measurable aspect of health or health services","Replaces all clinical judgement","Always proves causation","Contains no numerical information"],"correctIndex":0,"explanation":"Indicators help monitor health status, service performance and trends.","explanationNe":"सूचकले स्वास्थ्य अवस्था र सेवाको प्रगति मापन तथा अनुगमन गर्न मद्दत गर्छ।","topic":"Health indicators"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Community diagnosis is primarily concerned with:","translation":"","options":["Identifying community health problems and their determinants","Diagnosing one patient only","Auditing hospital income","Selecting medicines for one ward"],"correctIndex":0,"explanation":"Community diagnosis assesses population needs, problems, resources and determinants.","explanationNe":"समुदायको स्वास्थ्य समस्या, आवश्यकता, स्रोत र निर्धारक पहिचान गर्नु community diagnosis हो।","topic":"Community diagnosis"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Which is a social determinant of health?","translation":"","options":["Education and income","Blood group only","Laboratory reagent brand","Microscope magnification"],"correctIndex":0,"explanation":"Education, income, housing and employment influence health opportunities and outcomes.","explanationNe":"शिक्षा, आम्दानी, आवास र रोजगारीले स्वास्थ्यमा प्रभाव पार्छन्।","topic":"Social determinants"}'::jsonb,true),
