('bmlt-healthpolicy1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"The Sustainable Development Goal most directly focused on health is:","translation":"","options":["SDG 3: Good Health and Well-being","SDG 4: Quality Education","SDG 8: Decent Work","SDG 13: Climate Action"],"correctIndex":0,"explanation":"SDG 3 aims to ensure healthy lives and promote well-being for all at all ages.","explanationNe":"SDG 3 सबै उमेरका मानिसको स्वस्थ जीवन र कल्याणमा केन्द्रित छ।","topic":"SDGs"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A notifiable disease is one that:","translation":"","options":["Must be reported to public health authorities under applicable rules","Must never be recorded","Can only be diagnosed in private hospitals","Does not require surveillance"],"correctIndex":0,"explanation":"Mandatory notification supports surveillance and timely public health response.","explanationNe":"सूचित गर्नुपर्ने रोग सम्बन्धित जनस्वास्थ्य निकायलाई नियमअनुसार जानकारी गराइन्छ।","topic":"Disease notification"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"The denominator in a maternal mortality ratio is:","translation":"","options":["Live births","Total female population","Total pregnancies only","Total hospital admissions"],"correctIndex":0,"explanation":"Maternal mortality ratio is expressed per 100,000 live births.","explanationNe":"मातृ मृत्यु अनुपात सामान्यतया प्रति १ लाख जीवित जन्ममा व्यक्त गरिन्छ।","topic":"Vital statistics"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Health education is most effective when it is:","translation":"","options":["Participatory, understandable and culturally appropriate","One-way and full of jargon","Unrelated to community needs","Delivered without feedback"],"correctIndex":0,"explanation":"Participation and locally appropriate messages improve understanding and adoption.","explanationNe":"सहभागितामूलक र स्थानीय सन्दर्भअनुसारको शिक्षा बढी प्रभावकारी हुन्छ।","topic":"Health education"}'::jsonb,true),
('bmlt-healthpolicy1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"The main purpose of occupational health and safety in a laboratory is to:","translation":"","options":["Prevent work-related injury and exposure","Increase sample turnaround time only","Eliminate all documentation","Replace standard precautions"],"correctIndex":0,"explanation":"Occupational safety reduces biological, chemical, physical and ergonomic hazards.","explanationNe":"प्रयोगशालामा जैविक, रासायनिक तथा भौतिक जोखिमबाट कर्मचारीलाई जोगाउनु यसको उद्देश्य हो।","topic":"Occupational health"}'::jsonb,true),
('bmlt-healthpolicy1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A community reports a sudden rise in acute watery diarrhoea. What should public health staff do first?","translation":"","options":["Verify cases and determine whether an outbreak is occurring","Assume all cases have the same cause","Wait until the outbreak ends","Stop water-quality assessment"],"correctIndex":0,"explanation":"Initial verification confirms the diagnosis and excess occurrence before wider investigation.","explanationNe":"पहिले रोगको निदान र सामान्यभन्दा बढी केस भएको पुष्टि गर्नुपर्छ।","topic":"Outbreak investigation"}'::jsonb,true),
('bmlt-healthpolicy1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A screening test is offered to apparently healthy people to identify early disease. This is:","translation":"","options":["Secondary prevention","Primary prevention","Tertiary prevention","Rehabilitation"],"correctIndex":0,"explanation":"Screening detects disease early in people without symptoms.","explanationNe":"लक्षण नदेखिएका व्यक्तिमा रोग छिटो पत्ता लगाउनु द्वितीयक रोकथाम हो।","topic":"Levels of prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A district hospital receives a patient referred from a health post. This illustrates:","translation":"","options":["A referral pathway between levels of care","Primary prevention","Disease notification","Community sanitation"],"correctIndex":0,"explanation":"Referral connects primary facilities with higher-level diagnostic and treatment services.","explanationNe":"स्वास्थ्य चौकीबाट जिल्ला अस्पताल पठाउनु सेवा तहबीचको रेफरल हो।","topic":"Referral system"}'::jsonb,true),
('bmlt-healthpolicy1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A programme provides essential services while protecting households from catastrophic medical costs. Its central goal is:","translation":"","options":["Universal Health Coverage","Tertiary prevention","Passive surveillance","Private-sector expansion only"],"correctIndex":0,"explanation":"UHC seeks service access without financial hardship.","explanationNe":"UHC को लक्ष्य आर्थिक भार नपरी आवश्यक स्वास्थ्य सेवा उपलब्ध गराउनु हो।","topic":"UHC"}'::jsonb,true),
('bmlt-healthpolicy1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A health officer counts newly diagnosed tuberculosis cases during one calendar year. Which measure is being assessed?","translation":"","options":["Incidence","Point prevalence","Case fatality only","Crude birth rate"],"correctIndex":0,"explanation":"New cases over a defined period are used to calculate incidence.","explanationNe":"एक वर्षमा देखिएका नयाँ केस incidence मापन गर्न प्रयोग हुन्छन्।","topic":"Health indicators"}'::jsonb,true),
