('bmlt-healthpolicy1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A vaccine shipment is exposed to temperatures outside its recommended range. What is the appropriate response?","translation":"","options":["Quarantine the affected stock and follow vaccine cold-chain guidance","Use it immediately without documentation","Mix it with unaffected stock","Discard all vaccines in the district"],"correctIndex":0,"explanation":"Potentially compromised vaccines should be segregated and assessed according to official guidance.","explanationNe":"तापक्रम बिग्रिएको खोप छुट्याएर आधिकारिक निर्देशनअनुसार मूल्याङ्कन गर्नुपर्छ।","topic":"Immunization"}'::jsonb,true),
('bmlt-healthpolicy1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A village has repeated diarrhoeal outbreaks linked to unsafe wells. The most relevant intervention is:","translation":"","options":["Improve water safety and sanitation","Increase antibiotic use in all residents","Stop disease reporting","Focus only on hospital construction"],"correctIndex":0,"explanation":"Safe water, sanitation and hygiene interrupt faecal-oral transmission.","explanationNe":"सुरक्षित पानी, सरसफाइ र स्वच्छताले दिसा–मुखबाट सर्ने संक्रमण रोक्छ।","topic":"Environmental health"}'::jsonb,true),
('bmlt-healthpolicy1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A health centre reports cases regularly even when no outbreak is occurring. This is:","translation":"","options":["Routine surveillance","Outbreak-only investigation","A clinical trial","A census"],"correctIndex":0,"explanation":"Routine surveillance continuously collects health information over time.","explanationNe":"नियमित surveillance ले निरन्तर स्वास्थ्य तथ्याङ्क संकलन गर्छ।","topic":"Surveillance"}'::jsonb,true),
('bmlt-healthpolicy1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A health team maps local disease patterns, risk factors and available resources before planning services. This is:","translation":"","options":["Community diagnosis","Case-control matching","Hospital discharge coding","Drug procurement"],"correctIndex":0,"explanation":"Community diagnosis guides planning using local needs, determinants and resources.","explanationNe":"स्थानीय आवश्यकता, जोखिम र स्रोत पहिचान गरी योजना बनाउनु community diagnosis हो।","topic":"Community diagnosis"}'::jsonb,true),
('bmlt-healthpolicy1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A programme measures deaths among children younger than one year per 1,000 live births. This is:","translation":"","options":["Infant mortality rate","Maternal mortality ratio","Crude death rate","Incidence rate"],"correctIndex":0,"explanation":"The infant mortality rate uses infant deaths and live births in its denominator.","explanationNe":"शिशु मृत्यु दरमा एक वर्षमुनिका मृत्यु र जीवित जन्मको अनुपात प्रयोग हुन्छ।","topic":"Vital statistics"}'::jsonb,true),
('bmlt-healthpolicy1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A maternal death measure is reported per 100,000 live births. Which indicator is this?","translation":"","options":["Maternal mortality ratio","Infant mortality rate","Neonatal incidence","General fertility rate"],"correctIndex":0,"explanation":"Maternal mortality ratio is conventionally expressed per 100,000 live births.","explanationNe":"मातृ मृत्यु अनुपात प्रति १ लाख जीवित जन्ममा व्यक्त गरिन्छ।","topic":"Vital statistics"}'::jsonb,true),
('bmlt-healthpolicy1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A health campaign asks residents to participate in identifying local priorities and solutions. This approach is:","translation":"","options":["Community participation","Top-down instruction only","Clinical case management","Passive reporting"],"correctIndex":0,"explanation":"Participation gives communities a role in decisions affecting their health.","explanationNe":"समुदायको सहभागिताले स्वास्थ्यसम्बन्धी निर्णयमा स्थानीय मानिसको भूमिका सुनिश्चित गर्छ।","topic":"Health promotion"}'::jsonb,true),
