('bmlt-healthpolicy1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A patient with a long-term disability receives physiotherapy to improve daily function. This is:","translation":"","options":["Tertiary prevention","Primary prevention","Primordial prevention","Screening"],"correctIndex":0,"explanation":"Rehabilitation limits disability and improves function after disease or injury.","explanationNe":"रोगपछि कार्यक्षमता सुधार्ने पुनर्स्थापना तृतीयक रोकथाम हो।","topic":"Levels of prevention"}'::jsonb,true),
('bmlt-healthpolicy1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A public health team identifies education, housing and employment as influences on local health. These are:","translation":"","options":["Social determinants of health","Laboratory quality indicators","Clinical symptoms","Vaccine contraindications"],"correctIndex":0,"explanation":"Social and economic conditions shape health risks and opportunities.","explanationNe":"सामाजिक तथा आर्थिक अवस्थाले स्वास्थ्य जोखिम र अवसर निर्धारण गर्छन्।","topic":"Social determinants"}'::jsonb,true),
